let sym1 = Symbol("id");
let sym2 = Symbol("id");

console.log(sym1 === sym2);  // false — always unique!

// Symbols as object keys
let user = {
  [Symbol("id")]: 123,
  name: "Alex"
};

// Symbol keys are invisible to normal iteration
console.log(Object.keys(user));  // ["name"]
console.log(user[Symbol("id")]);  // undefined (different symbol!)

// Store the symbol to access the value
let id = Symbol("id");
user[id] = 123;
console.log(user[id]);  // 123

// module-a.js
let sym = Symbol.for("app.shared");
let obj = { [sym]: "data from A" };

// module-b.js (different file!)
let sameSym = Symbol.for("app.shared");
console.log(sym === sameSym);  // true!
console.log(obj[sameSym]);     // "data from A"

// Look up the key
console.log(Symbol.keyFor(sameSym));  // "app.shared"

class Range {
  constructor(start, end) {
    this.start = start;
    this.end = end;
  }

  [Symbol.iterator]() {
    let current = this.start;
    let end = this.end;
    return {
      next() {
        if (current <= end) {
          return { value: current++, done: false };
        }
        return { done: true };
      }
    };
  }
}

let range = new Range(1, 5);
for (let num of range) {
  console.log(num);  // 1, 2, 3, 4, 5
}

let doubled = [...range].map(n => n * 2);
console.log(doubled);  // [2, 4, 6, 8, 10]
